package io.zekumo.sdk;
import com.fasterxml.jackson.databind.JsonNode; import java.net.*; import java.net.http.*; import java.util.*; import java.util.concurrent.*; import java.util.function.*;
public final class ZekumoRealtime implements WebSocket.Listener,AutoCloseable {
 private final ZekumoClient c; private WebSocket ws; private final Map<String,List<Consumer<JsonNode>>> handlers=new ConcurrentHashMap<>(); private final StringBuilder input=new StringBuilder();
 ZekumoRealtime(ZekumoClient c){this.c=c;} public CompletableFuture<ZekumoRealtime> connect(){String u=c.baseUrl.replaceFirst("^http","ws")+"/v1/ws?token="+ZekumoClient.seg(c.token());return c.http.newWebSocketBuilder().buildAsync(URI.create(u),this).thenApply(x->{ws=x;return this;});}
 public ZekumoRealtime on(String e,Consumer<JsonNode> h){handlers.computeIfAbsent(e,k->new CopyOnWriteArrayList<>()).add(h);return this;} public CompletableFuture<WebSocket> send(String type,Object data){try{var n=c.json.createObjectNode().put("type",type);if(data!=null)n.set("data",c.json.valueToTree(data));return ws.sendText(c.json.writeValueAsString(n),true);}catch(Exception e){return CompletableFuture.failedFuture(e);}}
 public CompletionStage<?> onText(WebSocket w,CharSequence d,boolean last){input.append(d);if(last)try{var n=c.json.readTree(input.toString());input.setLength(0);handlers.getOrDefault(n.path("type").asText(),List.of()).forEach(h->h.accept(n.get("data")));}catch(Exception ignored){}w.request(1);return null;} public void onOpen(WebSocket w){w.request(1);} public void close(){if(ws!=null)ws.sendClose(1000,"");}
 public void createRoom(String n,int max,Object meta){send("room.create",ZekumoClient.map("name",n,"max_players",max,"meta",meta));} public void joinRoom(String id){send("room.join",ZekumoClient.map("room_id",id));} public void leaveRoom(){send("room.leave",null);} public void listRooms(){send("room.list",null);} public void state(Object s){send("room.state",ZekumoClient.map("state",s));} public void roomMessage(Object d){send("room.msg",ZekumoClient.map("data",d));} public void subscribe(String c){send("chat.sub",ZekumoClient.map("channel",c));} public void unsubscribe(String c){send("chat.unsub",ZekumoClient.map("channel",c));} public void chat(String c,String x){send("chat.send",ZekumoClient.map("channel",c,"content",x));}
}
